struct MSF {
    uint8 m, s, f;
};

inline MSF FADToMSF(uint32 fad) {
    MSF msf{};
    msf.m = fad / 75 / 60;
    msf.s = fad / 75 % 60;
    msf.f = fad % 75;
    return msf;
}

