enum class CartType { None, BackupMemory, DRAM8Mbit, DRAM32Mbit, DRAM48Mbit, ROM };

class BackupMemoryCartridge;
class DRAM8MbitCartridge;
class DRAM32MbitCartridge;
class DRAM48MbitCartridge;
