inline constexpr auto kCondTable = [] {
    std::array<bool, 16 * 16> arr{};
    for (uint32 nzvc = 0; nzvc < 16; nzvc++) {
        const bool n = bit::test<3>(nzvc);
        const bool z = bit::test<2>(nzvc);
        const bool v = bit::test<1>(nzvc);
        const bool c = bit::test<0>(nzvc);

        arr[(0u << 4u) | nzvc] = true;          
        arr[(1u << 4u) | nzvc] = false;         
        arr[(2u << 4u) | nzvc] = !c && !z;      
        arr[(3u << 4u) | nzvc] = c || z;        
        arr[(4u << 4u) | nzvc] = !c;            
        arr[(5u << 4u) | nzvc] = c;             
        arr[(6u << 4u) | nzvc] = !z;            
        arr[(7u << 4u) | nzvc] = z;             
        arr[(8u << 4u) | nzvc] = !v;            
        arr[(9u << 4u) | nzvc] = v;             
        arr[(10u << 4u) | nzvc] = !n;           
        arr[(11u << 4u) | nzvc] = n;            
        arr[(12u << 4u) | nzvc] = n == v;       
        arr[(13u << 4u) | nzvc] = n != v;       
        arr[(14u << 4u) | nzvc] = n == v && !z; 
        arr[(15u << 4u) | nzvc] = n != v || z;  
    }
    return arr;
}();



