class format_int {
 private:
  
  
  enum { buffer_size = std::numeric_limits<unsigned long long>::digits10 + 3 };
  mutable char buffer_[buffer_size];
  char* str_;

  template <typename UInt>
  constexpr auto format_unsigned(UInt value) -> char* {
    auto n = static_cast<detail::uint32_or_64_or_128_t<UInt>>(value);
    return detail::do_format_decimal(buffer_, n, buffer_size - 1);
  }

  template <typename Int>
  constexpr auto format_signed(Int value) -> char* {
    auto abs_value = static_cast<detail::uint32_or_64_or_128_t<Int>>(value);
    bool negative = value < 0;
    if (negative) abs_value = 0 - abs_value;
    auto begin = format_unsigned(abs_value);
    if (negative) *--begin = '-';
    return begin;
  }

 public:
  constexpr explicit format_int(int value) : str_(format_signed(value)) {}
  constexpr explicit format_int(long value)
      : str_(format_signed(value)) {}
  constexpr explicit format_int(long long value)
      : str_(format_signed(value)) {}
  constexpr explicit format_int(unsigned value)
      : str_(format_unsigned(value)) {}
  constexpr explicit format_int(unsigned long value)
      : str_(format_unsigned(value)) {}
  constexpr explicit format_int(unsigned long long value)
      : str_(format_unsigned(value)) {}

  
  constexpr auto size() const -> size_t {
    return detail::to_unsigned(buffer_ - str_ + buffer_size - 1);
  }

  
  
  constexpr auto data() const -> const char* { return str_; }

  
  
  constexpr auto c_str() const -> const char* {
    buffer_[buffer_size - 1] = '\0';
    return str_;
  }

  
  inline auto str() const -> std::string { return {str_, size()}; }
};



