enum class BusID {
    ABus,
    BBus,
    WRAM,
    None,
};

inline BusID GetBusID(uint32 address) {
    address &= 0x7FF'FFFF;
     if (util::AddressInRange<0x200'0000, 0x58F'FFFF>(address)) {
        return BusID::ABus;
    } else if (util::AddressInRange<0x5A0'0000, 0x5FB'FFFF>(address)) {
        return BusID::BBus;
    } else if (address >= 0x600'0000) {
        return BusID::WRAM;
    } else {
        return BusID::None;
    }
}

