    uint8 dmaSrc;        
    uint8 dmaDst;        
    uint32 dmaReadAddr;  
    uint32 dmaWriteAddr; 
    uint32 dmaAddrInc;   
    uint32 dmaAddrD0;    
    uint32 dmaPC;        

private:
    sys::SH2Bus &m_bus;

    CBTriggerDSPEnd m_cbTriggerDSPEnd;

    uint64 m_cyclesSpillover;

    debug::ISCUTracer *m_tracer = nullptr;

    void IncrementPC();

    
    template <bool debug>
    inline void RunPendingDMA(uint8 ctIndex) {
        if (dmaRun && ctIndex == (dmaToD0 ? dmaSrc : dmaDst)) {
            RunDMA<debug>(0);
        }
    }

    


