struct RegCCR {
    RegCCR() {
        Reset();
    }

    void Reset() {
        CE = false;
        ID = false;
        OD = false;
        TW = false;
        CP = false;
        Wn = 0;
    }

    inline uint8 Read() const {
        uint8 value = 0;
        bit::deposit_into<0>(value, CE);
        bit::deposit_into<1>(value, ID);
        bit::deposit_into<2>(value, OD);
        bit::deposit_into<3>(value, TW);
        bit::deposit_into<4>(value, CP);
        bit::deposit_into<6, 7>(value, Wn);
        return value;
    }

    inline void Write(uint8 value) {
        CE = bit::test<0>(value);
        ID = bit::test<1>(value);
        OD = bit::test<2>(value);
        TW = bit::test<3>(value);
        CP = bit::test<4>(value);
        Wn = bit::extract<6, 7>(value);
    }

    bool CE;
    bool ID;
    bool OD;
    bool TW;
    bool CP;
    uint8 Wn;
};






