        bit::deposit_into<3>(value, bgParams[4].mosaicEnable);
        bit::deposit_into<4>(value, bgParams[0].mosaicEnable);
        bit::deposit_into<8, 11>(value, mosaicH - 1);
        bit::deposit_into<12, 15>(value, mosaicV - 1);
