struct GouraudStepper {
    
    inline void Setup(uint32 length, Color555 gouraudStart, Color555 gouraudEnd) {
        m_r.Setup(length, gouraudStart.r, gouraudEnd.r);
        m_g.Setup(length, gouraudStart.g, gouraudEnd.g);
        m_b.Setup(length, gouraudStart.b, gouraudEnd.b);
    }

    
    inline void Step() {
        m_r.Step();
        m_g.Step();
        m_b.Step();
    }

    
    
    inline void Skip(uint32 steps) {
        if (steps > 0) {
            m_r.Skip(steps);
            m_g.Skip(steps);
            m_b.Skip(steps);
        }
    }

    
    inline Color555 Value() const {
        return Color555{
            .r = m_r.Value(),
            .g = m_g.Value(),
            .b = m_b.Value(),
        };
    }

    
    inline Color555 Blend(Color555 baseColor) const {
        return Color555{
            .r = m_r.Blend(baseColor.r),
            .g = m_g.Blend(baseColor.g),
            .b = m_b.Blend(baseColor.b),
            .msb = baseColor.msb,
        };
    }

private:
    GouraudChannelStepper m_r;
    GouraudChannelStepper m_g;
    GouraudChannelStepper m_b;
};


struct LineStepper {
    inline LineStepper(CoordS32 coord1, CoordS32 coord2, bool antiAlias = false) {
        auto [x1, y1] = coord1;
        auto [x2, y2] = coord2;

        m_x = x1;
        m_y = y1;
        m_xEnd = x2;
        m_yEnd = y2;
        m_antiAlias = antiAlias;

        sint32 dx = x2 - x1;
        sint32 dy = y2 - y1;
        sint32 adx = abs(dx);
        sint32 ady = abs(dy);
        m_dmaj = std::max(adx, ady);
        m_length = m_dmaj + 1;
        m_step = 0;

        const bool xMajor = adx >= ady;
        if (xMajor) {
            m_xMajInc = dx >= 0 ? +1 : -1;
            m_yMajInc = 0;
            m_xMinInc = 0;
            m_yMinInc = dy >= 0 ? +1 : -1;
        } else {
            m_xMajInc = 0;
            m_yMajInc = dy >= 0 ? +1 : -1;
            m_xMinInc = dx >= 0 ? +1 : -1;
            m_yMinInc = 0;
            std::swap(dx, dy);
            std::swap(adx, ady);
        }
        m_num = ady << 1;
        m_den = adx << 1;
        m_accum = adx + 1;
        m_accumTarget = 0;
        if (!antiAlias && dx < 0) {
            ++m_accumTarget;
        }
        m_accum += m_num;

        m_x -= m_xMajInc;
        m_y -= m_yMajInc;

        if (antiAlias) {
            --m_accum;
            --m_accumTarget;
            const bool samesign = (x1 > x2) == (y1 > y2);
            if (xMajor) {
                m_aaXInc = samesign ? 0 : -m_xMajInc;
                m_aaYInc = samesign ? -m_yMinInc : 0;
            } else {
                m_aaXInc = samesign ? 0 : -m_xMinInc;
                m_aaYInc = samesign ? -m_yMajInc : 0;
            }
        }

        
        static constexpr sint32 kShift = 32 - 13;

        m_num <<= kShift;
        m_den <<= kShift;
        m_accum <<= kShift;
        m_accumTarget <<= kShift;
    }

    
    
    inline uint32 SystemClip(sint32 width, sint32 height) {
        static constexpr sint32 kPadding = 1;

        
        width += kPadding + 1;
        height += kPadding + 1;

        
        uint32 length = m_dmaj;
        if (length == 0u) {
            return 0u;
        }

        const sint32 xs = m_x;
        const sint32 ys = m_y;
        const sint32 xe = m_xEnd;
        const sint32 ye = m_yEnd;

        
        if (xs >= -kPadding && xs <= width && ys >= -kPadding && ys <= height && xe >= -kPadding && xe <= width &&
            ye >= -kPadding && ye <= height) {
            return 0u;
        }

        
        if ((xs < -kPadding && xe < -kPadding) || (xs > width && xe > width) || (ys < -kPadding && ye < -kPadding) ||
            (ys > height && ye > height)) {
            m_x = m_xEnd;
            m_y = m_yEnd;
            m_length = 0u;
            return 0u;
        }

        

        const bool xmajor = m_xMajInc != 0;
        const sint32 inc = m_xMajInc + m_yMajInc; 
        const sint32 start = xmajor ? xs : ys;
        const sint32 end = xmajor ? xe : ye;
        const sint32 maxLen = xmajor ? width : height;

        
        uint32 startClip = 0u;
        if (inc > 0 && start < -kPadding) {
            startClip = -start - 1 - kPadding;
        } else if (inc < 0 && start > maxLen) {
            startClip = start - maxLen;
        }
        if (startClip > 0u) {
            startClip = std::min(startClip, length - 1u);
            m_x += m_xMajInc * startClip;
            m_y += m_yMajInc * startClip;
            for (uint32 i = 0; i < startClip; ++i) {
                m_accum -= m_num;
                if (m_den != 0) {
                    while (m_accum <= m_accumTarget) {
                        m_accum += m_den;
                        m_x += m_xMinInc;
                        m_y += m_yMinInc;
                    }
                }
            }
            length -= startClip;
        }

        

        
        uint32 endClip = 0u;
        if (inc < 0 && end < -kPadding) {
            endClip = -end - 1 - kPadding;
        } else if (inc > 0 && end > maxLen) {
            endClip = end - maxLen;
        }
        endClip = std::min(endClip, length);
        if (endClip > 0u) {
            endClip = length - endClip;
            length = endClip;
            m_xEnd = m_x;
            m_yEnd = m_y;
            sint32 tempAccum = m_accum;
            for (uint32 i = 0; i < endClip; ++i) {
                tempAccum -= m_num;
                if (m_den != 0) {
                    while (tempAccum <= m_accumTarget) {
                        tempAccum += m_den;
                        m_xEnd += m_xMinInc;
                        m_yEnd += m_yMinInc;
                    }
                }
            }
        }
        m_length = length + 1u;

        return startClip;
    }

    
    inline bool CanStep() const {
        return m_step <= m_length;
    }

    
    
    
    inline bool Step() {
        ++m_step;
        m_x += m_xMajInc;
        m_y += m_yMajInc;
        m_accum -= m_num;
        if (m_accum <= m_accumTarget) {
            m_accum += m_den;
            m_x += m_xMinInc;
            m_y += m_yMinInc;
            return m_antiAlias;
        }
        return false;
    }

    
    inline sint32 X() const {
        return m_x & 0x7FF;
    }

    
    inline sint32 Y() const {
        return m_y & 0x7FF;
    }

    
    inline CoordS32 Coord() const {
        return {m_x, m_y};
    }

    
    inline sint32 AAX() const {
        return m_x + m_aaXInc;
    }

    
    inline sint32 AAY() const {
        return m_y + m_aaYInc;
    }

    
    inline CoordS32 AACoord() const {
        return {AAX(), AAY()};
    }

    
    inline uint32 Length() const {
        return m_dmaj;
    }

private:
    sint32 m_num;
    sint32 m_den;
    sint32 m_accum;
    sint32 m_accumTarget;

    sint32 m_xMajInc;
    sint32 m_yMajInc;
    sint32 m_xMinInc;
    sint32 m_yMinInc;

    sint32 m_x;
    sint32 m_y;
    sint32 m_xEnd;
    sint32 m_yEnd;

    uint32 m_dmaj;
    uint32 m_step;
    uint32 m_length;

    sint32 m_aaXInc;
    sint32 m_aaYInc;
    bool m_antiAlias;
};

struct Edge {
    inline void Setup(CoordS32 coord1, CoordS32 coord2, uint32 delta) {
        auto [x1, y1] = coord1;
        auto [x2, y2] = coord2;

        const sint32 dx = bit::sign_extend<13>(x2 - x1);
        const sint32 dy = bit::sign_extend<13>(y2 - y1);
        const uint32 adx = abs(dx);
        const uint32 ady = abs(dy);
        m_dmaj = std::max(adx, ady);

        m_x = x1;
        m_y = y1;

        m_xInc = dx >= 0 ? +1 : -1;
        m_yInc = dy >= 0 ? +1 : -1;

        m_xNum = adx << 1;
        m_yNum = ady << 1;

        m_xDen = m_yDen = m_dmaj << 1;
        m_xAccum = m_yAccum = ~m_dmaj;

        m_xAccumTarget = dy < 0 ? -1 : 0;
        m_yAccumTarget = dx < 0 ? -1 : 0;

        m_num = m_dmaj << 1;
        m_den = delta << 1;
        m_accum = ~delta;
        m_accumTarget = adx >= ady ? m_yAccumTarget : m_xAccumTarget;

        
        static constexpr sint32 kShift = 32 - 13;

        m_xNum <<= kShift;
        m_yNum <<= kShift;
        m_xDen <<= kShift;
        m_yDen <<= kShift;
        m_xAccum <<= kShift;
        m_yAccum <<= kShift;
        m_xAccumTarget <<= kShift;
        m_yAccumTarget <<= kShift;

        m_num <<= kShift;
        m_den <<= kShift;
        m_accum <<= kShift;
        m_accumTarget <<= kShift;

        m_gouraudEnable = false;
    }

    
    inline void SetupGouraud(Color555 start, Color555 end) {
        m_gouraud.Setup(m_dmaj + 1, start, end);
        m_gouraudEnable = true;
    }

    
    inline void Step() {
        m_accum += m_num;
        if (m_accum >= m_accumTarget) {
            m_accum -= m_den;

            m_xAccum += m_xNum;
            if (m_xAccum >= m_xAccumTarget) {
                m_xAccum -= m_xDen;
                m_x += m_xInc;
            }

            m_yAccum += m_yNum;
            if (m_yAccum >= m_yAccumTarget) {
                m_yAccum -= m_yDen;
                m_y += m_yInc;
            }

            if (m_gouraudEnable) {
                m_gouraud.Step();
            }
        }
    }

    
    inline sint32 X() const {
        return m_x;
    }

    
    inline sint32 Y() const {
        return m_y;
    }

    
    inline CoordS32 Coord() const {
        return {m_x, m_y};
    }

    
    inline const GouraudStepper &Gouraud() const {
        return m_gouraud;
    }

    
    inline Color555 GouraudValue() const {
        return m_gouraud.Value();
    }

private:
    GouraudStepper m_gouraud;
    bool m_gouraudEnable;

    uint32 m_dmaj;

    sint32 m_x, m_y;
    sint32 m_xInc, m_yInc;
    sint32 m_xNum, m_yNum;
    sint32 m_xDen, m_yDen;
    sint32 m_xAccum, m_yAccum;
    sint32 m_xAccumTarget, m_yAccumTarget;

    sint32 m_num;
    sint32 m_den;
    sint32 m_accum;
    sint32 m_accumTarget;
};










struct QuadStepper {
    inline QuadStepper(CoordS32 coordA, CoordS32 coordB, CoordS32 coordC, CoordS32 coordD) {
        const uint32 deltaLx = abs(bit::sign_extend<13>(coordD.x() - coordA.x()));
        const uint32 deltaLy = abs(bit::sign_extend<13>(coordD.y() - coordA.y()));
        const uint32 deltaRx = abs(bit::sign_extend<13>(coordC.x() - coordB.x()));
        const uint32 deltaRy = abs(bit::sign_extend<13>(coordC.y() - coordB.y()));

        m_dmaj = std::max(std::max(deltaLx, deltaLy), std::max(deltaRx, deltaRy)) & 0xFFF;
        m_step = 0;

        m_edgeL.Setup(coordA, coordD, m_dmaj);
        m_edgeR.Setup(coordB, coordC, m_dmaj);
    }

    
    inline void SetupTexture(TextureStepper &stepper, uint32 charSizeV, bool flipV) const {
        sint32 start = 0;
        sint32 end = charSizeV - 1;
        if (flipV) {
            std::swap(start, end);
        }
        stepper.Setup(m_dmaj + 1, start, end);
    }

    
    inline void SetupGouraud(Color555 colorA, Color555 colorB, Color555 colorC, Color555 colorD) {
        m_edgeL.SetupGouraud(colorA, colorD);
        m_edgeR.SetupGouraud(colorB, colorC);
    }

    
    inline const Edge &LeftEdge() const {
        return m_edgeL;
    }

    
    inline const Edge &RightEdge() const {
        return m_edgeR;
    }

    
    inline bool CanStep() const {
        return m_step <= m_dmaj;
    }

    
    
    
    
    inline void Step() {
        ++m_step;

        m_edgeL.Step();
        m_edgeR.Step();
    }

private:
    Edge m_edgeL; 
    Edge m_edgeR; 

    uint32 m_dmaj;
    uint32 m_step;
};

